async (prefs: CookiePreferences) => {
    const consentId = localStorage.getItem("cookie_consent_id") || crypto.randomUUID();
    const consentData = {
      consentId,
      preferences: prefs,
      timestamp: new Date().toISOString(),
      expiresAt: new Date(
        Date.now() + 365 * 24 * 60 * 60 * 1000
      ).toISOString(), // 1 year
    };

    // Save to localStorage
    localStorage.setItem("cookie_consent_id", consentId);
    localStorage.setItem("cookie_consent", JSON.stringify(consentData));

    // Save to backend
    try {
      await fetch("/api/gdpr/cookie-consent", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Idempotency-Key": consentId,
        },
        body: JSON.stringify({
          consentId,
          userId,
          organizationId,
          ...prefs,
          ipAddress: undefined, // Server will capture this
          userAgent: navigator.userAgent,
        }),
      });
    } catch (_error) {
}

    applyConsent(prefs);
  }

