(): boolean => {
    const newErrors = new Map<string, string>();
    let isValid = true;

    for (const question of questions) {
      const error = validateQuestion(question);
      if (error) {
        newErrors.set(question.id, error);
        isValid = false;
      }
    }

    setErrors(newErrors);
    return isValid;
  }

