        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: note }),
      });
      if (res.ok) {
        setCases(cases.map(c =>
          c.id === caseItem.id
            ? { ...c, notes: [...c.notes, note], lastUpdate: new Date().toISOString().split('T')[0] }
