async (voteId: string, optionId: string) => {
    setIsSubmitting(voteId);

    try {
      const response = await fetch(`/api/voting/sessions/${voteId}/vote`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ optionId }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to submit vote');
      }

      // Update local state to reflect vote
      setVotes(prevVotes => 
        prevVotes.map(v => 
          v.id === voteId 
            ? { ...v, hasVoted: true, userVote: optionId }
            : v
        )
      );
      setSelectedOption(prev => ({ ...prev, [voteId]: optionId }));

      // Refresh votes to get updated counts
      const refreshResponse = await fetch('/api/voting/sessions');
      if (refreshResponse.ok) {
        const res = await refreshResponse.json();
        const apiSessions = res.data?.sessions || res.sessions || [];
        setVotes(mapSessions(apiSessions));
      }
    } catch (err) {
alert(err instanceof Error ? err.message : 'Failed to submit vote');
    } finally {
      setIsSubmitting(null);
    }
  }

(format: "csv" | "excel") => {
    if (onExport) {
      onExport(format);
      return;
    }

    // Default CSV export
    if (format === "csv") {
      const headers = table
        .getAllColumns()
        .filter((col) => col.getIsVisible())
        .map((col) => col.id);

      const rows = table.getFilteredRowModel().rows.map((row) =>
        headers.map((header) => {
          const value = row.getValue(header);
          return typeof value === "string" ? `"${value}"` : value;
        })
      );

      const csv = [
        headers.join(","),
        ...rows.map((row) => row.join(",")),
      ].join("\n");

      const blob = new Blob([csv], { type: "text/csv" });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `export-${new Date().toISOString()}.csv`;
      a.click();
      window.URL.revokeObjectURL(url);
    }
  }

