useCallback(async (file: File) => {
    if (attachments.length >= maxFiles) {
      toast({
        title: 'Maximum files reached',
        description: `You can only upload up to ${maxFiles} files per claim.`,
        variant: 'destructive',
      });
      return;
    }

    setUploading(true);

    try {
      const formData = new FormData();
      formData.append('file', file);

      const response = await fetch(`/api/cases/${claimId}/evidence`, {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Upload failed');
      }

      const newAttachment = data?.data?.attachment ?? data?.attachment;
      if (!newAttachment) {
        throw new Error('Upload completed without attachment metadata');
      }
      setAttachments(prev => [...prev, newAttachment]);

      toast({
        title: 'Upload successful',
        description: `${file.name} has been uploaded.`,
      });

      onUploadComplete?.(newAttachment);
    } catch (error) {
toast({
        title: 'Upload failed',
        description: error instanceof Error ? error.message : 'Failed to upload file',
        variant: 'destructive',
      });
    } finally {
      setUploading(false);
    }
  }, [attachments.length, maxFiles, claimId, toast, onUploadComplete])

