async (content?: string) => {
    const messageContent = content || inputValue.trim();

    if (!messageContent || isLoading) return;

    // Create session if none exists
    let activeSession = currentSession;
    if (!activeSession) {
      activeSession = await createNewSession();
      if (!activeSession) return; // session creation failed
    }

    setInputValue("");
    setShowSuggestions(false);
    setIsLoading(true);

    // Add user message optimistically
    const tempUserMessage: Message = {
      id: `temp-${Date.now()}`,
      role: "user",
      content: messageContent,
    };

    setMessages((prev) => [...prev, tempUserMessage]);

    try {
      const response = await fetch("/api/chatbot/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          sessionId: activeSession.id,
          content: messageContent,
          useRAG: true,
        }),
      });

      if (!response.ok) {
        throw new Error("Failed to send message");
      }

      const data = await response.json();
      // withApi envelope: { success, data: { data: row } }
      const msg = data?.data?.data ?? data?.data ?? data?.message;

      // Replace temp message with real one and add assistant response
      setMessages((prev) => [
        ...prev.filter((m) => m.id !== tempUserMessage.id),
        {
          id: `user-${Date.now()}`,
          role: "user",
          content: messageContent,
        },
        {
          id: msg.id,
          role: "assistant",
          content: msg.content,
          retrievedDocuments: msg.retrievedDocuments,
          tokensUsed: msg.tokensUsed,
          responseTimeMs: msg.responseTimeMs,
        },
      ]);

      // Update session in list
      if (currentSession) {
        setSessions((prev) =>
          prev.map((s) =>
            s.id === currentSession.id
              ? {
                  ...s,
                  messageCount: s.messageCount + 2,
                  lastMessageAt: new Date().toISOString(),
                }
              : s
          )
        );
      }
    } catch (_error) {
      toast({
        title: "Error",
        description: "Failed to send message. Please try again.",
        variant: "destructive",
      });

      // Remove temp message on error
      setMessages((prev) => prev.filter((m) => m.id !== tempUserMessage.id));
    } finally {
      setIsLoading(false);
    }
  }

